import csv, collections
rows = collections.defaultdict(list)
for fn in ['round-001-s11.csv','round-002-s11.csv','round-003-s11.csv','round-004-s11.csv','round-005-s11.csv','round-006-s11.csv','round-007-s11.csv','round-009-s11.csv']:
    with open(fn) as f:
        for r in csv.DictReader(f):
            rows[(fn.split('-')[1][:3]+':'+r['variation'])].append((float(r['freq_ghz']), float(r['s11_db'])))
def segs(pts):
    pts.sort(); freqs=[p[0] for p in pts]; s11=[p[1] for p in pts]
    out=[]; i=0; n=len(s11)
    while i<n:
        if s11[i]<=-10:
            j=i
            while j+1<n and s11[j+1]<=-10: j+=1
            out.append((freqs[i],freqs[j])); i=j+1
        else: i+=1
    return out
res=[]
for k,pts in rows.items():
    ss=segs(pts)
    for fL,fH in ss:
        if fL<=77.0<=fH:
            res.append((2*(fH-fL)/(fH+fL)*100,fL,fH,k))
res.sort(key=lambda r:-r[0])
print("=== segments containing 77 GHz, top 12 ===")
for fbw,fL,fH,k in res[:12]:
    print(f"FBW {fbw:5.2f}%  {fL:6.2f}-{fH:6.2f}  {k}")
print(f"\ntotal traces: {len(rows)}, with-77 segments: {len(res)}")
EOF

